  cfg.auth?.headers?.forEach((k, v) => headers[k] = v);
  resolved.forEach((k, v) => headers[k] = v);
  return headers;
}

/// Adds the operation's header parameters; its cookies join an auth cookie.
void _addOperationHeaders(
  Map<String, String> headers,
  Map<String, String>? operationHeaders,
) {
  operationHeaders?.forEach((name, value) {
    final existing = headers[name];
    headers[name] =
        name == 'Cookie' && existing != null ? '$value; $existing' : value;
  });
}

class _AuthResolved {
  final Map<String, String> headers;
  final Map<String, dynamic> query;
  _AuthResolved(this.headers, this.query);
}

Future<_AuthResolved> _resolveAuth(ClientConfig cfg, String operationId) async {
  final headers = <String, String>{};
  final query = <String, dynamic>{};
  final auth = cfg.auth;

  if (auth == null) return _AuthResolved(headers, query);

  if (auth.bearerToken != null) {
    headers["Authorization"] = "Bearer ${auth.bearerToken!}";
  }

  if (auth.oauth2 != null) {
    final token = await (auth.oauth2!.provider != null
        ? _providerAccessToken(
            auth.oauth2!.provider!,
            operationId,
            _oauth2TokenRequest(
                "oauth2",
                "https://api.vercel.com/oauth/access_token",
                "https://api.vercel.com/oauth/access_token",
                operationId))
        : _resolveOAuth2Token(
            auth.oauth2!, "https://api.vercel.com/oauth/access_token"));
    headers["Authorization"] = "Bearer $token";
  }

  return _AuthResolved(headers, query);
}

final Map<String, _OAuth2CacheEntry> _oauth2Cache = {};
const Duration _oauth2ExpirySkew = Duration(seconds: 30);

// Token requests in flight, per owner and key, so concurrent requests that find
// the same token missing or expired share one request to the endpoint.
final Expando<Map<String, Future<Object?>>> _oauth2InFlight = Expando();

Future<T> _singleFlight<T>(
    Object owner, String key, Future<T> Function() fetch) {
  final calls = _oauth2InFlight[owner] ??= {};
  final pending = calls[key];
  if (pending != null) return pending as Future<T>;
  // A block body: `remove` returns this very future, and `whenComplete` would
  // wait on it and never complete.
  final call = fetch().whenComplete(() {
    calls.remove(key);
  });
  calls[key] = call;
  return call;
}

const _operationScopes = <String, Map<String, List<String>>>{};

OAuth2TokenRequest _oauth2TokenRequest(String scheme, String tokenUrl,
        String refreshUrl, String operationId) =>
    OAuth2TokenRequest(scheme, tokenUrl, refreshUrl,
        _operationScopes[operationId]?[scheme] ?? const []);

bool _usableOAuth2Token(OAuth2Token token) =>
    token.accessToken.isNotEmpty &&
    (token.expiresAt == null ||
        token.expiresAt!.isAfter(DateTime.now().add(_oauth2ExpirySkew)));

SdkAuthProviderError _oauth2ProviderError(
  String operationId,
  OAuth2TokenRequest request,
  String summary, [
  Object? cause,
]) {
  final suffix = operationId.isEmpty ? "" : " for operation $operationId";
  return SdkAuthProviderError(operationId, request.scheme, request.scopes,
      "auth oauth2 $summary$suffix", cause);
}

/// Asks the provider for a token, and for a refresh when that token is not usable.
Future<String> _providerAccessToken(
  OAuth2TokenProvider provider,
  String operationId,
  OAuth2TokenRequest request,
) async {
  OAuth2Token token;
  try {
    token = await provider.getAccessToken(request);
  } catch (error) {
    throw _oauth2ProviderError(
        operationId, request, "could not obtain an access token", error);
  }
  if (_usableOAuth2Token(token)) return token.accessToken;
  try {
    final scopes = (request.scopes.toList()..sort()).join(" ");
    token = await _singleFlight(provider, "${request.scheme}|$scopes",
        () => provider.refreshAccessToken(request));
  } catch (error) {
    throw _oauth2ProviderError(operationId, request,
        "could not refresh the expired access token", error);
  }
  if (_usableOAuth2Token(token)) return token.accessToken;
  throw _oauth2ProviderError(
      operationId, request, "obtained no usable access token");
}

class _OAuth2CacheEntry {
  final String accessToken;
  final DateTime expiresAt;
  _OAuth2CacheEntry(this.accessToken, this.expiresAt);
}

Future<String> _resolveOAuth2Token(
    OAuth2Auth auth, String defaultTokenUrl) async {
  if (auth.accessToken != null) return auth.accessToken!;
  final tokenUrl = auth.tokenUrl ?? defaultTokenUrl;
  if (tokenUrl.isEmpty) {
    throw SdkNetworkError(
        "oauth2: tokenUrl is required for client credentials flow");
  }
  final sortedScopes = (auth.scopes ?? []).toList()..sort();
  final cacheKey = "${auth.clientId ?? ""}|$tokenUrl|${sortedScopes.join(",")}";
  final cached = _oauth2Cache[cacheKey];
  if (cached != null &&
      cached.expiresAt.isAfter(DateTime.now().add(_oauth2ExpirySkew))) {
    return cached.accessToken;
  }
  return _singleFlight(_oauth2Cache, cacheKey,
      () => _exchangeClientCredentials(auth, tokenUrl, cacheKey));
}

/// Runs the client-credentials grant and caches the issued token.
Future<String> _exchangeClientCredentials(
    OAuth2Auth auth, String tokenUrl, String cacheKey) async {
  final form = <String, String>{
    "grant_type": "client_credentials",
    "client_id": auth.clientId ?? "",
    "client_secret": auth.clientSecret ?? "",
  };
  if (auth.scopes != null && auth.scopes!.isNotEmpty) {
    form["scope"] = auth.scopes!.join(" ");
  }
  final payload = await _postTokenForm(tokenUrl, form);
  if (payload["access_token"] is! String) {
    throw SdkNetworkError("oauth2: token response missing access_token");
  }
  final accessToken = payload["access_token"] as String;
  _oauth2Cache[cacheKey] =
      _OAuth2CacheEntry(accessToken, _oauth2ExpiresAt(payload));
  return accessToken;
}

DateTime _oauth2ExpiresAt(Map<Object?, Object?> payload) {
  final expiresIn = payload["expires_in"];
  return DateTime.now()
      .add(Duration(seconds: expiresIn is num ? expiresIn.toInt() : 3600));
}

/// POSTs a token-endpoint form and returns the decoded JSON object, or an
/// empty map when the response is not one.
Future<Map<Object?, Object?>> _postTokenForm(
    String tokenUrl, Map<String, String> form) async {
  final body = form.entries
      .map((e) =>
          "${Uri.encodeComponent(e.key)}=${Uri.encodeComponent(e.value)}")
      .join("&");

  final client = HttpClient();
  try {
    final req = await client.postUrl(Uri.parse(tokenUrl));
    req.headers.set("Content-Type", "application/x-www-form-urlencoded");
    req.headers.set("Accept", "application/json");
    final bodyBytes = utf8.encode(body);
    req.headers
        .set(HttpHeaders.contentLengthHeader, bodyBytes.length.toString());
    req.add(bodyBytes);
    final resp = await req.close();
    final text = await resp.transform(utf8.decoder).join();
    if (resp.statusCode < 200 || resp.statusCode >= 300) {
      throw SdkHttpError.forStatus(resp.statusCode, utf8.encode(text));
    }
    final payload = jsonDecode(text);
    return payload is Map ? payload : const {};
  } finally {
    client.close();
  }
}

/// The built-in provider for the refresh-token grant: it refreshes the access
/// token before it expires and adopts each refresh token the server rotates
/// in, passing it to [onRefreshTokenRotated] so it can be persisted.
class OAuth2RefreshTokenProvider implements OAuth2TokenProvider {
  String _refreshToken;
  final String? clientId;
  final String? clientSecret;

  /// Overrides the request's refreshUrl.
  final String? refreshUrl;
  final FutureOr<void> Function(String refreshToken)? onRefreshTokenRotated;
  OAuth2Token _token = const OAuth2Token("");

  OAuth2RefreshTokenProvider(
    String refreshToken, {
    this.clientId,
    this.clientSecret,
    this.refreshUrl,
    this.onRefreshTokenRotated,
  }) : _refreshToken = refreshToken;

  @override
  Future<OAuth2Token> getAccessToken(OAuth2TokenRequest request) async =>
      _token;

  @override
  Future<OAuth2Token> refreshAccessToken(OAuth2TokenRequest request) async {
    final form = <String, String>{
      "grant_type": "refresh_token",
      "refresh_token": _refreshToken,
      if (clientId != null) "client_id": clientId!,
      if (clientSecret != null) "client_secret": clientSecret!,
    };
    final payload =
        await _postTokenForm(refreshUrl ?? request.refreshUrl, form);
    final accessToken = payload["access_token"];
    _token = OAuth2Token(
      accessToken is String ? accessToken : "",
      expiresAt: _oauth2ExpiresAt(payload),
    );
    final rotated = payload["refresh_token"];
    if (rotated is String && rotated.isNotEmpty && rotated != _refreshToken) {
      _refreshToken = rotated;
      await onRefreshTokenRotated?.call(rotated);
    }
    return _token;
  }
}

/// A PKCE code verifier and the S256 challenge derived from it (RFC 7636).
class OAuth2PkcePair {
  final String verifier;
  final String challenge;

  const OAuth2PkcePair(this.verifier, this.challenge);

  String get method => "S256";
}

/// The tokens an authorization code is redeemed for; persist [refreshToken]
/// to renew access without another login.
class OAuth2AuthorizationCodeTokens {
  final String accessToken;
  final DateTime expiresAt;
  final String? refreshToken;

  const OAuth2AuthorizationCodeTokens(this.accessToken, this.expiresAt,
      {this.refreshToken});
}

/// Creates a PKCE verifier and its S256 challenge. Keep the verifier with the
/// login attempt until its authorization code is exchanged.
OAuth2PkcePair createPkcePair() {
  final random = Random.secure();
  final verifier =
      _base64Url(List<int>.generate(32, (_) => random.nextInt(256)));
  return OAuth2PkcePair(
      verifier, _base64Url(sha256.convert(ascii.encode(verifier)).bytes));
}

String _base64Url(List<int> bytes) =>
    base64Url.encode(bytes).replaceAll("=", "");

/// The authorization-code URL to send the user to. The application owns the
/// browser, the redirect, and checking [state] when the user comes back.
/// [authorizationUrl] overrides the spec's.
String buildAuthorizationUrl({
  required String clientId,
  required String redirectUri,
  required String codeChallenge,
  List<String> scopes = const [],
  String? state,
  String? authorizationUrl,
}) {
  final base =
      Uri.parse(authorizationUrl ?? "https://api.vercel.com/oauth/authorize");
  return base.replace(queryParameters: {
    ...base.queryParameters,
    "response_type": "code",
    "client_id": clientId,
    "redirect_uri": redirectUri,
    "code_challenge": codeChallenge,
    "code_challenge_method": "S256",
    if (scopes.isNotEmpty) "scope": scopes.join(" "),
    if (state != null) "state": state,
  }).toString();
}

/// Redeems an authorization code and its PKCE verifier at the token endpoint.
/// [tokenUrl] overrides the spec's.
Future<OAuth2AuthorizationCodeTokens> exchangeAuthorizationCode({
  required String code,
  required String codeVerifier,
  required String redirectUri,
  required String clientId,
  String? clientSecret,
  String? tokenUrl,
}) async {
  final form = <String, String>{
    "grant_type": "authorization_code",
    "code": code,
    "redirect_uri": redirectUri,
    "client_id": clientId,
    "code_verifier": codeVerifier,
    if (clientSecret != null) "client_secret": clientSecret,
  };
  final payload = await _postTokenForm(
      tokenUrl ?? "https://api.vercel.com/oauth/access_token", form);
  final accessToken = payload["access_token"];
  if (accessToken is! String) {
    throw SdkNetworkError("oauth2: token response missing access_token");
  }
  final refreshToken = payload["refresh_token"];
  return OAuth2AuthorizationCodeTokens(
    accessToken,
    _oauth2ExpiresAt(payload),
    refreshToken: refreshToken is String ? refreshToken : null,
  );
}

bool _shouldRetry(String method, int statusCode, List<int> retryOn) {
  if (!retryOn.contains(statusCode)) return false;
  if (_idempotentMethods.contains(method)) return true;
  return _alwaysRetryableStatuses.contains(statusCode);
}

/// An attempt that produced no response may already have been applied, so a
/// non-idempotent method is repeated only with a key sent to an operation
/// that declares the server deduplicates on it.
bool _mayRepeatRequest(
    String method, String operationId, String? idempotencyKey) {
  if (_idempotentMethods.contains(method)) return true;
  return idempotencyKey != null &&
      _idempotencyKeyOperations.contains(operationId);
}

Future<void> _sleepBackoff(
  RetryConfig retry,
  int attempt,
  String? retryAfter,
  Random rng,
) async {
  Duration delay;

  if (retryAfter != null) {
    final seconds = int.tryParse(retryAfter.trim());
    if (seconds != null && seconds > 0) {
      delay = Duration(seconds: seconds);
      if (delay > retry.maxBackoff) delay = retry.maxBackoff;
      await Future<void>.delayed(delay);
      return;
    }
  }

  final exp = retry.backoff * pow(2, attempt - 1);
  final jitterMs = rng.nextInt(retry.backoff.inMilliseconds);
  delay = exp + Duration(milliseconds: jitterMs);
  if (delay > retry.maxBackoff) delay = retry.maxBackoff;
  await Future<void>.delayed(delay);
}

/// One Server-Sent Event yielded by [sdkStream]. [data] is JSON-decoded when
/// the payload looks like JSON ({...} or [...]) and stays a raw string
/// otherwise — sentinels like `[DONE]` arrive as strings so consumers can
/// terminate explicitly.
class SdkStreamEvent {
  final String event;
  final dynamic data;
  final String? id;
  final int? retry;

  const SdkStreamEvent(
      {required this.event, required this.data, this.id, this.retry});
}

/// Opens an SSE connection and returns a Stream of parsed events. Bypasses
/// the retry loop and idempotency layer — streaming connections are
/// long-lived; reconnect is the caller's responsibility.
Stream<SdkStreamEvent> sdkStream(
  String method,
  String path, {
  ClientConfig? config,
  Map<String, dynamic>? query,
  Object? body,
  String contentType = 'application/json',
  Map<String, String>? extraHeaders,
  String operationId = '',
  String streamFormat = 'sse',
  String streamMediaType = 'text/event-stream',
  String chunkDomain = 'bytes',
  RequestOptions? options,
  Map<String, Object? Function(Object?)> errors = const {},
}) async* {
  final cfg = config ?? SdkConfig.getConfig();
  final timeout = cfg.timeout ?? const Duration(seconds: 30);
  final isAbsolute = path.startsWith('http://') || path.startsWith('https://');
  var url = isAbsolute
      ? path
      : '${cfg.baseUrl ?? _operationServers[operationId] ?? SdkConfig.defaultBaseUrl}$path';

  final authResolved = await _resolveAuth(cfg, operationId);
  final mergedQuery =
      authResolved.query.isEmpty ? query : {...?query, ...authResolved.query};
  if (mergedQuery != null && mergedQuery.isNotEmpty) {
    final queryString = SdkUtils.buildQueryString(mergedQuery);
    url += url.contains('?') ? '&${queryString.substring(1)}' : queryString;
  }

  // Use the same body encoder as unary requests so multipart streams receive a
  // real boundary and binary bodies remain byte-faithful.
  List<int>? outBytes;
  body = _withStreamSelector(body, operationId, contentType);
  if (identical(body, sdkOmittedValue)) {
    // No request body.
  } else if (_formFields(body) case final fields?
      when contentType.startsWith('multipart/form-data')) {
    final rng = Random();
    final boundary =
        '----InterfacerFormBoundary${rng.nextInt(1 << 31)}${DateTime.now().microsecondsSinceEpoch}';
    outBytes = _encodeMultipart(fields, boundary);
    contentType = 'multipart/form-data; boundary=$boundary';
  } else if (body is List<int>) {
    outBytes = body;
  } else if (body != null) {
    outBytes = utf8.encode(_encodeJsonBody(body, contentType));
  }

  final headers = _authHeadersFor(cfg, authResolved.headers);
  _addOperationHeaders(headers, extraHeaders);
  if (options != null) headers.addAll(options.headers);
  headers['Accept'] = streamMediaType;
  if (body != null && !identical(body, sdkOmittedValue)) {
    headers['content-type'] = contentType;
  }

  final client = HttpClient();
  client.connectionTimeout = timeout;
  try {
    final uri = Uri.parse(url);
    final req = await client.openUrl(method, uri);
    for (final entry in headers.entries) {
      req.headers.set(entry.key, entry.value);
    }
    if (outBytes != null) {
      req.headers
          .set(HttpHeaders.contentLengthHeader, outBytes.length.toString());
      req.add(outBytes);
    }

    final resp = await req.close();
    if (resp.statusCode < 200 || resp.statusCode >= 300) {
      final body = await resp
          .fold<List<int>>(<int>[], (out, chunk) => out..addAll(chunk));
      final respHeaders = _flatHeaders(resp);
      throw SdkHttpError.forStatus(
        resp.statusCode,
        body,
        headers: respHeaders,
        requestId: _findRequestIdLocal(respHeaders) ?? '',
        errors: errors,
      );
    }
    // A server that ignored the stream flag answers with plain JSON, which the
    // event parser would read as no events at all.
    final answerType = resp.headers.value(HttpHeaders.contentTypeHeader) ?? '';
    final mediaType = answerType.split(';').first.trim().toLowerCase();
    if (streamFormat == 'sse' &&
        (mediaType == 'application/json' || mediaType.endsWith('+json'))) {
      final body = await resp
          .fold<List<int>>(<int>[], (out, chunk) => out..addAll(chunk));
      final respHeaders = _flatHeaders(resp);
      throw SdkResponseDecodeError(
        'Expected an event stream, received $answerType',
        statusCode: resp.statusCode,
        headers: respHeaders,
        rawBody: body,
        requestId: _findRequestIdLocal(respHeaders) ?? '',
      );
    }

    if (streamFormat == 'chunked') {
      await for (final chunk in resp) {
        yield SdkStreamEvent(
          event: 'chunk',
          data: chunkDomain == 'text' ? utf8.decode(chunk) : chunk,
        );
      }
      return;
    }

    if (streamFormat == 'ndjson') {
      await for (final line
          in resp.transform(utf8.decoder).transform(const LineSplitter())) {
        if (line.trim().isNotEmpty) {
          // A JSON text sequence record also starts with RS.
          yield SdkStreamEvent(
              event: 'message',
              data: _decodeStreamJson(line.replaceFirst('\u001e', '')));
        }
      }
      return;
    }

    String? eventName;
    String? eventId;
    int? eventRetry;
    final dataLines = <String>[];

    dynamic parsePayload(String raw) {
      final trimmed = raw.trim();
      if (trimmed == '[DONE]') return trimmed;
      if (trimmed.startsWith('{') || trimmed.startsWith('[')) {
        return _decodeStreamJson(raw);
      }
      return raw;
    }

    await for (final line
        in resp.transform(utf8.decoder).transform(const LineSplitter())) {
      if (line.isEmpty) {
        if (dataLines.isNotEmpty) {
          yield SdkStreamEvent(
            event: eventName ?? 'message',
            data: parsePayload(dataLines.join('\n')),
            id: eventId,
            retry: eventRetry,
          );
          dataLines.clear();
          eventName = null;
        }
        continue;
      }
      if (line.startsWith(':')) continue;
      final colon = line.indexOf(':');
      final field = colon == -1 ? line : line.substring(0, colon);
      var value = colon == -1 ? '' : line.substring(colon + 1);
      if (value.startsWith(' ')) value = value.substring(1);
      switch (field) {
        case 'event':
          eventName = value;
          break;
        case 'data':
          dataLines.add(value);
          break;
        case 'id':
          eventId = value;
          break;
        case 'retry':
          eventRetry = int.tryParse(value);
          break;
      }
    }
    if (dataLines.isNotEmpty) {
      yield SdkStreamEvent(
        event: eventName ?? 'message',
        data: parsePayload(dataLines.join('\n')),
        id: eventId,
        retry: eventRetry,
      );
    }
  } finally {
    client.close(force: true);
  }
}

dynamic _decodeStreamJson(String payload) {
  try {
    return SdkUtils.decodeJson(payload);
  } on FormatException catch (error) {
    throw SdkStreamParseError(payload, error);
  }
}

/// The response's headers, one value each, keyed by lower-case name.
Map<String, String> _flatHeaders(HttpClientResponse resp) {
  final headers = <String, String>{};
  resp.headers.forEach((name, values) {
    if (values.isNotEmpty) headers[name.toLowerCase()] = values.first;
  });
  return headers;
}

String? _findRequestIdLocal(Map<String, String> headers) {
  for (final h in _requestIdHeaders) {
    final v = headers[h];
    if (v != null) return v;
  }
  return null;
}

/// Configuration for [waitFor].
class WaitForConfig {
  final Duration interval;
  final Duration maxInterval;
  final Duration timeout;

  const WaitForConfig({
    this.interval = const Duration(seconds: 1),
    this.maxInterval = const Duration(seconds: 30),
    this.timeout = const Duration(minutes: 10),
  });
}

class TerminalState {
  final bool done;
  final bool failed;
  final String? reason;
  const TerminalState({required this.done, this.failed = false, this.reason});

  static const pending = TerminalState(done: false);
  static const success = TerminalState(done: true);
  static TerminalState failure(String? reason) =>
      TerminalState(done: true, failed: true, reason: reason);
}

/// Polls a long-running operation until terminal. [isTerminal] classifies
/// each result. Throws [SdkTimeoutError] on deadline.
Future<T> waitFor<T>(
  Future<T> Function() poll,
  TerminalState Function(T) isTerminal, {
  WaitForConfig config = const WaitForConfig(),
}) async {
  final rng = Random();
  final deadline = DateTime.now().add(config.timeout);
  var interval = config.interval;
  while (true) {
    final result = await poll();
    final state = isTerminal(result);
    if (state.done) {
      if (state.failed) {
        throw SdkNetworkError('operation failed: ${state.reason ?? "unknown"}');
      }
      return result;
    }
    if (DateTime.now().isAfter(deadline)) {
      throw SdkTimeoutError(config.timeout);
    }
    final jitterMs = rng.nextInt(config.interval.inMilliseconds + 1);
    var wait = interval + Duration(milliseconds: jitterMs);
    if (wait > config.maxInterval) wait = config.maxInterval;
    await Future<void>.delayed(wait);
    interval = interval * 2;
    if (interval > config.maxInterval) interval = config.maxInterval;
  }
}
